17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.util.UriComponentsBuilder;
44	
45	import jakarta.transaction.Transactional;
46	
47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    private final ClinicService clinicService;
57	
58	    private final OwnerMapper ownerMapper;
59	
60	    private final PetMapper petMapper;
61	
62	    private final VisitMapper visitMapper;
63	
64	    public OwnerRestControllerV1(ClinicService clinicService,
65	                                 OwnerMapper ownerMapper,
66	                                 PetMapper petMapper,
67	                                 VisitMapper visitMapper) {
68	        this.clinicService = clinicService;
69	        this.ownerMapper = ownerMapper;
70	        this.petMapper = petMapper;
71	        this.visitMapper = visitMapper;
72	    }
73	
74	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
75	    @Override
76	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
77	        Collection<Owner> owners;
78	        if (lastName != null) {
79	            owners = this.clinicService.findOwnerByLastName(lastName);
80	        } else {
81	            owners = this.clinicService.findAllOwners();
82	        }
83	        if (owners.isEmpty()) {
84	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
85	        }
86	        List<OwnerDto> ownerDtos = ownerMapper.toOwnerDtoCollection(owners);
87	        boolean bulkSignupWarning = this.clinicService.isBulkSignupWarningActive();
88	        ownerDtos.forEach(ownerDto -> ownerDto.setBulkSignupWarning(bulkSignupWarning));
89	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(withBulkSignupWarning(ownerMapper.toOwnerDto(owner)), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        this.clinicService.saveOwner(owner);
108	        OwnerDto ownerDto = withBulkSignupWarning(ownerMapper.toOwnerDto(owner));
109	        headers.setLocation(UriComponentsBuilder.newInstance()
110	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
111	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
117	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
118	        if (currentOwner == null) {
119	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
120	        }
121	        currentOwner.setAddress(ownerFieldsDto.getAddress());
122	        currentOwner.setCity(ownerFieldsDto.getCity());
123	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
124	        currentOwner.setLastName(ownerFieldsDto.getLastName());
125	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
126	        currentOwner.setEmail(ownerFieldsDto.getEmail());
127	        this.clinicService.saveOwner(currentOwner);
128	        return new ResponseEntity<>(withBulkSignupWarning(ownerMapper.toOwnerDto(currentOwner)),
129	            HttpStatus.NO_CONTENT);
130	    }
131	
132	    /**
133	     * Sets the response-level {@code bulkSignupWarning} flag on {@code ownerDto} from the service's
134	     * current daily-signup assessment. The warning is a property of the current day's signup volume,
135	     * so it is the same for every owner returned in a single response.
136	     */
137	    private OwnerDto withBulkSignupWarning(OwnerDto ownerDto) {
138	        ownerDto.setBulkSignupWarning(this.clinicService.isBulkSignupWarningActive());
139	        return ownerDto;
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Transactional
144	    @Override
145	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
146	        Owner owner = this.clinicService.findOwnerById(ownerId);
147	        if (owner == null) {
148	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
149	        }
150	        this.clinicService.deleteOwner(owner);
151	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
152	    }
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Override
156	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
157	        Owner owner = this.clinicService.findOwnerById(ownerId);
158	        if (owner == null) {
159	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
160	        }
161	        HttpHeaders headers = new HttpHeaders();
162	        Pet pet = petMapper.toPet(petFieldsDto);
163	        owner.setId(ownerId);
164	        pet.setOwner(owner);
165	        pet.getType().setName(null);
166	        this.clinicService.savePet(pet);
167	        PetDto petDto = petMapper.toPetDto(pet);
168	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
169	            .buildAndExpand(pet.getId()).toUri());
170	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
176	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
177	        if (currentOwner != null) {
178	            Pet currentPet = this.clinicService.findPetById(petId);
179	            if (currentPet != null) {
180	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
181	                currentPet.setName(petFieldsDto.getName());
182	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
183	                this.clinicService.savePet(currentPet);
184	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
185	            }
186	        }
187	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Override
192	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
193	        HttpHeaders headers = new HttpHeaders();
194	        Visit visit = visitMapper.toVisit(visitFieldsDto);
195	        Pet pet = new Pet();
196	        pet.setId(petId);
197	        visit.setPet(pet);
198	        this.clinicService.saveVisit(visit);
199	        VisitDto visitDto = visitMapper.toVisitDto(visit);
200	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
201	            .buildAndExpand(visit.getId()).toUri());
202	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
203	    }
204	
205	
206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Override
208	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
209	        Owner owner = this.clinicService.findOwnerById(ownerId);
210	        if (owner != null) {
211	            Pet pet = owner.getPet(petId);
212	            if (pet != null) {
213	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
214	            }
215	        }
216	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
217	    }
218	}
