31	/**
32	 * Simple JavaBean domain object representing an owner.
33	 *
34	 * @author Ken Krebs
35	 * @author Juergen Hoeller
36	 * @author Sam Brannen
37	 * @author Michael Isvy
38	 */
39	@Entity
40	@Table(name = "owners")
41	public class Owner extends Person {
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "city")
47	    @NotEmpty
48	    private String city;
49	
50	    @Column(name = "telephone")
51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form (a leading '+' and 8 to 15 digits)")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    @Email
57	    private String email;
58	
59	    @Column(name = "registration_date")
60	    private LocalDate registrationDate;
61	
62	    @Column(name = "birth_date")
63	    private LocalDate birthDate;
64	
65	    @Column(name = "customer_code")
66	    private String customerCode;
67	
68	    @Column(name = "household_id")
69	    private String householdId;
70	
71	    @Column(name = "namesake_count")
72	    private Integer namesakeCount;
73	
74	    @Column(name = "postcode")
75	    private String postcode;
76	
77	    /**
78	     * Whether this owner was flagged as a suspected soft-duplicate of an existing owner. Retained
79	     * as part of the API/persistence contract but always {@code false} under the current
80	     * household-keyed rule: an owner sharing an existing owner's {@code lastName} and
81	     * {@code postcode} is now the same household, so it is either rejected as a household duplicate
82	     * (409) or admitted as a declared {@code sharesHousehold} member — and a declared member is not
83	     * a suspected duplicate. No production code path sets this field.
84	     */
85	    @Column(name = "possible_duplicate")
86	    private boolean possibleDuplicate;
87	
88	    /**
89	     * The id of the existing owner this owner soft-matches, set together with
90	     * {@link #isPossibleDuplicate()}. Retained for contract compatibility but always {@code null}
91	     * under the current household-keyed rule (see {@link #isPossibleDuplicate()}); no production
92	     * code path sets it.
93	     */
94	    @Column(name = "possible_duplicate_of")
95	    private Integer possibleDuplicateOf;
96	
97	    /**
98	     * Write-only, non-persistent acknowledgement that this owner deliberately shares a
99	     * household with an existing owner. When {@code true}, creation is allowed even if
100	     * another owner already has the same lastName and address.
101	     */
102	    @Transient
103	    private boolean sharesHousehold;
104	
105	    /**
106	     * Read-only, non-persistent count of the owners that share this owner's {@code householdId}
107	     * (including this owner), populated by the service when an owner is loaded for presentation.
108	     * Zero when the owner belongs to no household. Used to derive the membership tier.
109	     */
110	    @Transient
111	    private int householdSize;
112	
113	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
114	    private Set<Pet> pets;
115	
116	    public String getAddress() {
117	        return this.address;
118	    }
119	
120	    public void setAddress(String address) {
121	        this.address = address;
122	    }
123	
124	    public String getCity() {
125	        return this.city;
126	    }
127	
128	    public void setCity(String city) {
129	        this.city = city;
130	    }
131	
132	    public String getTelephone() {
133	        return this.telephone;
134	    }
135	
136	    public void setTelephone(String telephone) {
137	        this.telephone = telephone;
138	    }
139	
140	    /**
141	     * The stored E.164 {@link #getTelephone() telephone} formatted for human display: the
142	     * country code, a space, then the national digits grouped in threes (e.g.
143	     * {@code "+61 412 345 678"}). Null when no telephone is set.
144	     */
145	    public String getTelephoneDisplay() {
146	        return E164Telephone.toDisplay(this.telephone);
147	    }
148	
149	    public String getEmail() {
150	        return this.email;
151	    }
152	
153	    public void setEmail(String email) {
154	        this.email = email;
155	    }
156	
157	    public LocalDate getRegistrationDate() {
158	        return this.registrationDate;
159	    }
160	
161	    public void setRegistrationDate(LocalDate registrationDate) {
162	        this.registrationDate = registrationDate;
163	    }
164	
165	    public LocalDate getBirthDate() {
166	        return this.birthDate;
167	    }
168	
169	    public void setBirthDate(LocalDate birthDate) {
170	        this.birthDate = birthDate;
171	    }
172	
173	    /**
174	     * The owner's age band derived from {@code birthDate} measured against {@code registrationDate}:
175	     * {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or
176	     * over. Returns null when either the birth date or the registration date is not set.
177	     */
178	    public String getAgeBand() {
179	        if (this.birthDate == null || this.registrationDate == null) {
180	            return null;
181	        }
182	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
183	        if (age < 18) {
184	            return "MINOR";
185	        }
186	        if (age < 65) {
187	            return "ADULT";
188	        }
189	        return "SENIOR";
190	    }
191	
192	    public String getCustomerCode() {
193	        return this.customerCode;
194	    }
195	
196	    public void setCustomerCode(String customerCode) {
197	        this.customerCode = customerCode;
198	    }
199	
200	    public String getHouseholdId() {
201	        return this.householdId;
202	    }
203	
204	    public void setHouseholdId(String householdId) {
205	        this.householdId = householdId;
206	    }
207	
208	    public Integer getNamesakeCount() {
209	        return this.namesakeCount;
210	    }
211	
212	    public void setNamesakeCount(Integer namesakeCount) {
213	        this.namesakeCount = namesakeCount;
214	    }
215	
216	    public String getPostcode() {
217	        return this.postcode;
218	    }
219	
220	    public void setPostcode(String postcode) {
221	        this.postcode = postcode;
222	    }
223	
224	    public boolean isPossibleDuplicate() {
225	        return this.possibleDuplicate;
226	    }
227	
228	    public void setPossibleDuplicate(boolean possibleDuplicate) {
229	        this.possibleDuplicate = possibleDuplicate;
230	    }
231	
232	    public Integer getPossibleDuplicateOf() {
233	        return this.possibleDuplicateOf;
234	    }
235	
236	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
237	        this.possibleDuplicateOf = possibleDuplicateOf;
238	    }
239	
240	    /** The household size at or above which an owner earns the household membership points. */
241	    public static final int MEMBERSHIP_HOUSEHOLD_SIZE = 3;
242	
243	    /** The number of tenure days beyond which an owner earns the tenure membership points. */
244	    public static final long MEMBERSHIP_TENURE_DAYS = 365;
245	
246	    /**
247	     * The owner's membership points, computed from stored fields: they start at 0, gain 2 when an
248	     * email is present, gain 1 when {@code namesakeCount} is 0, gain 2 for a household of
249	     * {@value #MEMBERSHIP_HOUSEHOLD_SIZE} or more (see {@link #getHouseholdSize()}), and gain 3 when
250	     * the owner's tenure (days elapsed since its {@code registrationDate}) exceeds
251	     * {@value #MEMBERSHIP_TENURE_DAYS}.
252	     */
253	    public int getMembershipPoints() {
254	        int points = 0;
255	        if (this.email != null && !this.email.isEmpty()) {
256	            points += 2;
257	        }
258	        if (this.namesakeCount != null && this.namesakeCount == 0) {
259	            points += 1;
260	        }
261	        if (this.householdSize >= MEMBERSHIP_HOUSEHOLD_SIZE) {
262	            points += 2;
263	        }
264	        if (this.registrationDate != null
265	                && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > MEMBERSHIP_TENURE_DAYS) {
266	            points += 3;
267	        }
268	        return points;
269	    }
270	
271	    /**
272	     * The owner's numeric membership level, mapped from {@link #getMembershipPoints()}: 1 for 0-1
273	     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
274	     */
275	    public int getMembershipLevel() {
276	        int points = getMembershipPoints();
277	        if (points >= 6) {
278	            return 4;
279	        }
280	        if (points >= 4) {
281	            return 3;
282	        }
283	        if (points >= 2) {
284	            return 2;
285	        }
286	        return 1;
287	    }
288	
289	    /**
290	     * The derived identity key used to detect duplicate owners: the (already normalized) telephone,
291	     * the email or empty, and the {@code householdId} or empty, joined with {@code '|'}. This single
292	     * key consolidates the former separate telephone, email and household duplicate rules — two
293	     * owners are duplicates only when their whole identity keys are equal. Because the telephone is
294	     * part of the key, two members of the same household (same {@code householdId}) with different
295	     * telephones have different keys and are both allowed.
296	     */
297	    public String getIdentityKey() {
298	        String tel = this.telephone == null ? "" : this.telephone;
299	        String mail = this.email == null ? "" : this.email;
300	        String household = this.householdId == null ? "" : this.householdId;
301	        return tel + "|" + mail + "|" + household;
302	    }
303	
304	    /**
305	     * A single Luhn check digit (0-9) computed over the digits contained in {@code customerCode},
306	     * or null when the {@code customerCode} has not been assigned.
307	     */
308	    public Integer getCheckDigit() {
309	        if (this.customerCode == null) {
310	            return null;
311	        }
312	        int sum = 0;
313	        boolean dbl = true;
314	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
315	            char c = this.customerCode.charAt(i);
316	            if (c < '0' || c > '9') {
317	                continue;
318	            }
319	            int d = c - '0';
320	            if (dbl) {
321	                d *= 2;
322	                if (d > 9) {
323	                    d -= 9;
324	                }
325	            }
326	            sum += d;
327	            dbl = !dbl;
328	        }
329	        return (10 - (sum % 10)) % 10;
330	    }
331	
332	    public boolean isSharesHousehold() {
333	        return this.sharesHousehold;
334	    }
335	
336	    public void setSharesHousehold(boolean sharesHousehold) {
337	        this.sharesHousehold = sharesHousehold;
338	    }
339	
340	    public int getHouseholdSize() {
341	        return this.householdSize;
342	    }
343	
344	    public void setHouseholdSize(int householdSize) {
345	        this.householdSize = householdSize;
346	    }
347	
348	    protected Set<Pet> getPetsInternal() {
349	        if (this.pets == null) {
350	            this.pets = new HashSet<>();
351	        }
352	        return this.pets;
353	    }
354	
355	    protected void setPetsInternal(Set<Pet> pets) {
356	        this.pets = pets;
357	    }
358	
359	    public List<Pet> getPets() {
