389	     */
390	    public Pet getPet(String name, boolean ignoreNew) {
391	        name = name.toLowerCase();
392	        for (Pet pet : getPetsInternal()) {
393	            if (!ignoreNew || !pet.isNew()) {
394	                String compName = pet.getName();
395	                compName = compName.toLowerCase();
396	                if (compName.equals(name)) {
397	                    return pet;
398	                }
399	            }
