298	    /**
299	     * Rejects saving {@code owner} when its email's domain is on the disposable-domain blocklist
300	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}). The email is optional: a {@code null} email is left
301	     * untouched. The comparison is case-insensitive on the part after the last {@code '@'}; the
302	     * email has already been lower-cased by {@link #saveOwner(Owner)} before this runs.
303	     *
304	     * @throws DisposableEmailDomainException if the email domain is blocklisted
305	     */
306	    private void assertEmailDomainAllowed(Owner owner) {
307	        String email = owner.getEmail();
308	        if (email == null) {
309	            return;
310	        }
311	        int at = email.lastIndexOf('@');
312	        if (at < 0) {
313	            return;
314	        }
315	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
316	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
317	            throw new DisposableEmailDomainException(domain);
318	        }
319	    }
