321	    @Override
322	    @Transactional
323	    public void saveOwner(Owner owner) throws DataAccessException {
324	        assertPostcodeValid(owner);
325	        assertRegistrationDateNotFuture(owner);
326	        if (owner.getTelephone() != null) {
327	            owner.setTelephone(normalizeTelephone(owner.getTelephone()));
328	        }
329	        if (owner.getEmail() != null) {
330	            owner.setEmail(normalizeEmail(owner.getEmail()));
331	        }
332	        assertEmailDomainAllowed(owner);
333	        if (owner.getAddress() != null) {
334	            owner.setAddress(normalizeAddress(owner.getAddress()));
335	        }
336	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
337	        owner.setRegistrationDate(rollToBusinessDay(effectiveDate));
338	        if (owner.getCustomerCode() == null) {
339	            owner.setCustomerCode(generateCustomerCode(owner));
340	        }
341	        boolean creating = owner.isNew();
342	        if (creating) {
343	            owner.setNamesakeCount(countNamesakes(owner));
344	            assertDailyCapacity(owner);
345	            assertCityCapacity(owner);
346	        }
347	        assignHouseholdId(owner);
348	        assertIdentityUnique(owner);
349	        if (creating) {
350	            assertHouseholdUnique(owner);
351	        }
352	        ownerRepository.save(owner);
353	        populateHouseholdSize(owner);
354	        if (creating) {
355	            AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
356	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
357	                owner.getMembershipLevel());
358	        }
359	    }
360	
361	    /**
362	     * Build a {@code customerCode} formatted {@code '<REGION>-<HASH8>'} where REGION is the region
363	     * code derived from the owner's postcode (see {@link Region#regionForPostcode(String)}) and
364	     * HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the concatenation of
365	     * the owner's normalized telephone and {@code lastName}. The telephone is already normalized by
366	     * {@link #saveOwner(Owner)} before this runs. The {@code '<REGION>-<HASH8>'} layout is read back
367	     * by {@link Region#regionOfCustomerCode(String)}; keep the two in sync.
368	     */
369	    private String generateCustomerCode(Owner owner) {
370	        String region = Region.regionForPostcode(owner.getPostcode());
371	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
372	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
373	        String hash8 = sha256UpperHex(telephone + lastName, 8);
374	        return region + "-" + hash8;
375	    }
376	
377	    /**
378	     * The first {@code chars} upper-case hex characters of the SHA-256 digest of {@code value}'s
379	     * UTF-8 bytes.
380	     */
381	    private static String sha256UpperHex(String value, int chars) {
382	        try {
383	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
384	            byte[] hash = digest.digest(value.getBytes(StandardCharsets.UTF_8));
385	            StringBuilder sb = new StringBuilder(hash.length * 2);
386	            for (byte b : hash) {
387	                sb.append(String.format("%02X", b));
388	            }
389	            return sb.substring(0, chars);
390	        } catch (NoSuchAlgorithmException e) {
391	            throw new IllegalStateException("SHA-256 not available", e);
392	        }
393	    }
