398	    /**
399	     * Rejects creating {@code owner} when its city already contains {@link #CITY_OWNER_LIMIT} or
400	     * more owners, so no city can grow beyond the capacity limit.
401	     *
402	     * @throws CityOwnerLimitException if the owner's city is already at capacity
403	     */
404	    private void assertCityCapacity(Owner owner) {
405	        if (owner.getCity() == null) {
406	            return;
407	        }
408	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
409	            throw new CityOwnerLimitException(owner.getCity(), CITY_OWNER_LIMIT);
410	        }
411	    }
