413	    /**
414	     * Rolls {@code date} forward to the next business day when it falls on a weekend: a Saturday or
415	     * Sunday becomes the following Monday. Business days (Monday to Friday) are returned unchanged.
416	     */
417	    private static LocalDate rollToBusinessDay(LocalDate date) {
418	        switch (date.getDayOfWeek()) {
419	            case SATURDAY:
420	                return date.plusDays(2);
421	            case SUNDAY:
422	                return date.plusDays(1);
423	            default:
424	                return date;
425	        }
426	    }
